'use strict';
const rules = [
 ['🔐','Keep passwords private.','Never send your password in a message, even for a prize or help with a game.'],
 ['🎁','Be careful with unexpected prizes.','If you did not enter a competition, stop and check before believing you have won.'],
 ['🔗','Don’t click strange links.','Ask a trusted grown-up before opening an unexpected link.'],
 ['⏰','Don’t let urgent messages rush you.','Pause if a message tries to frighten you or says you must act NOW.'],
 ['👀','Check who really sent the message.','A familiar name can be copied. Check strange messages another way.'],
 ['🌐','Look carefully at website names.','Watch for strange spelling, extra letters and unexpected links.'],
 ['🧠','Even professional-looking messages can be fake.','A logo, good spelling or your first name does not prove a message is real.'],
 ['🙋','If you’re unsure — ask a trusted grown-up.','If something makes you worried or confused, stop and ask for help.']
];
const levels = [
 {title:'The Surprise Prize',kind:'prize',context:'Puzzle time',scene:'Peep is playing a puzzle game on a tablet. Suddenly a colourful message appears.',sender:'A surprise pop-up',message:'🎉 CONGRATULATIONS!\nYOU WON A BRAND-NEW TABLET!\nCLICK HERE TO CLAIM YOUR PRIZE NOW!',dialogue:[['Peep','Wow! I don’t remember entering a competition.'],['Poppy','Hmm… what do you think?']],answer:'scam',reply:[['Poppy','Correct! It could be a scam.'],['Peep','If you didn’t enter a competition, be suspicious of messages saying you’ve suddenly won a prize.']],tips:['Unexpected prizes can be tricks to make you click.','Never click the link. Ask a trusted grown-up first.']},
 {title:'The School Website',kind:'school',context:'Planning sports day',scene:'Poppy wants to check what time the school sports day begins. She opens the school website that her teacher has used before.',sender:'Our familiar school website',message:'Greenfield Primary School\nSports Day – Friday, 10:00 AM',note:'There are no strange pop-ups or requests for passwords.',dialogue:[['Poppy','I’ve visited this school website with my teacher before.']],answer:'safe',reply:[['Peep','That’s right! This looks safe.'],['Poppy','It is a website we already know and trust, and it isn’t asking me for anything unusual.']],tips:['Websites you already know can be safer than strange links sent in unexpected messages.']},
 {title:'The Free Game Coins',kind:'coins',context:'A message in a game',scene:'Peep receives a message while playing his favourite game.',sender:'A player Peep does not know',message:'Hey!\nWant 10,000 FREE game coins?\nSend me your username and password and I’ll add them to your account!',dialogue:[['Peep','10,000 coins sounds brilliant…'],['Poppy','But they want your password!']],answer:'scam',reply:[['Peep','You spotted it!'],['Poppy','Never share your password for prizes, coins, skins or anything else.']],tips:['🔐 Passwords are private.','Real games and trusted companies should not ask you to send someone your password in a message.']},
 {title:'A Message From Grandma',kind:'family',context:'Pancakes tomorrow',scene:'Poppy receives a message. She recognises Grandma’s usual contact, and the message doesn’t ask her to click anything or share personal information.',sender:'Grandma · her usual contact',message:'Hi Poppy!\nIt’s Grandma.\nI’m making pancakes tomorrow.\nWould you like strawberries on yours? ❤️',dialogue:[['Peep','Do you recognise who sent it?'],['Poppy','Yes. It’s Grandma’s normal contact.']],answer:'safe',reply:[['Peep','Correct!'],['Poppy','It’s from someone I know using the contact I normally use.']],tips:['Knowing who sent a message is an important clue.','But remember: if a message from someone you know suddenly seems strange, check with them another way.']},
 {title:'Is It Really Mum?',kind:'unknown',context:'An unknown number',scene:'Peep receives a message from a number he doesn’t recognise. He looks worried.',sender:'Unknown number',message:'Hi Peep. It’s Mum.\nMy phone broke so I’m using a new number.\nDon’t call me.\nI need you to send me the password for our shopping account quickly.',dialogue:[['Peep','It says it’s Mum…'],['Poppy','But how do we know?']],answer:'scam',reply:[['Poppy','Excellent spotting!'],['Peep','Someone can pretend to be a person we know.']],tips:['A familiar name doesn’t always mean a message is genuine.'],checks:['A new or unknown number','Requests for passwords','Messages telling you not to check','Pressure to act quickly'],after:'Ask a trusted grown-up and check with the real person another way.'},
 {title:'The Urgent Account Warning',kind:'urgent',context:'An alarming email',scene:'Poppy receives an email with a large red button.',sender:'Video account warning',message:'⚠️ URGENT!\nYour video account will be DELETED IN 10 MINUTES!\nClick below and enter your password immediately!',fakeButton:'SAVE MY ACCOUNT NOW',dialogue:[['Poppy','Oh no! Only ten minutes!'],['Peep','Wait. Why are they trying to rush you?']],answer:'scam',reply:[['Peep','Exactly!'],['Poppy','Scammers sometimes try to make people frightened or rushed so they click before thinking.']],tips:['STOP — THINK — CHECK','If a message says “NOW! QUICK! URGENT! YOUR ACCOUNT WILL CLOSE!”, don’t panic.','Don’t use the link in the message. Ask a trusted grown-up and check the account another way.']},
 {title:'The Almost-Right Website',kind:'website',context:'Look at every letter',scene:'Peep wants to visit www.happygames.com. But a message sends him to www.happygamess.com. The page looks almost exactly like the real Happy Games website.',sender:'Happy Games',expected:'www.happygames.com',actual:'www.happygamess.com',message:'Sign in with your username and password.',dialogue:[['Peep','It looks exactly like Happy Games!'],['Poppy','Look carefully at the website name.']],answer:'scam',reply:[['Poppy','Well spotted!'],['Peep','There is an extra S in the web address!']],tips:['Fake websites can look almost identical to real ones.'],checks:['🔍 The website name','🔍 Strange spelling','🔍 Extra letters','🔍 Unexpected links'],after:'When unsure, don’t sign in. Ask a trusted grown-up.'},
 {title:'The Tricky Final Challenge',kind:'polished',context:'Your final case',scene:'Poppy gets a message that looks as though it came from a game she really uses. It has the game’s correct logo, good spelling, Poppy’s first name and professional-looking pictures.',sender:'Happy Games · Account team',message:'Hi Poppy,\nWe noticed a problem with your account.\nPlease confirm your details.',link:'www.happygames-account.example/confirm',note:'Poppy notices the link leads to a different website name from the game’s normal website.',dialogue:[['Poppy','This one looks real.'],['Peep','Yes… but we weren’t expecting it.']],answer:'scam',reply:[['Peep','You solved the hardest challenge!'],['Poppy','Scams don’t always look silly. Some can look very convincing.']],tips:['Don’t decide something is safe just because it has a logo, your name or professional pictures.','When something unexpected asks you to:'],checks:['Click a link','Sign in','Share information','Send money','Act quickly'],after:'STOP — THINK — CHECK. Ask a trusted grown-up before doing anything.'}
];
const stage=document.getElementById('stage');
let current=0,stars=0,screen='guidelines',solved=false,sound=false,audioContext;
const escapeHTML=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const art='card-bruno-warmth.png';
const dialogue=lines=>lines.map(([name,line])=>`<p class="speech ${name.toLowerCase()}"><strong>${name}</strong><span>“${escapeHTML(line)}”</span></p>`).join('');
const starRow=()=>`<ol class="star-trail" aria-label="${stars} of 8 Safety Stars collected">${levels.map((_,i)=>`<li class="${i<stars?'earned':''} ${screen==='level'&&i===current?'current':''}" aria-label="Safety Star ${i+1}${i<stars?' collected':''}"><span aria-hidden="true">★</span><small>${i+1}</small></li>`).join('')}</ol>`;
function navigate(name){screen=name;history.pushState({scamScreen:name},'');render();}
function render(){document.getElementById('back').hidden=screen==='guidelines';if(screen==='guidelines')guidelines();else if(screen==='mission')mission();else if(screen==='finish')finish();else level();window.scrollTo({top:0,behavior:'instant'});const heading=stage.querySelector('h1');if(heading)heading.focus({preventScroll:true});}
function guidelines(){stage.innerHTML=`<section class="guide"><div class="step">1 of 2 · Before we play</div><div class="guide-heading"><img src="${art}" alt="Peep and Poppy with their tablet and Mama Clover"><div><p class="eyebrow">STOP • THINK • CHECK</p><h1 tabindex="-1">Scam Spotter!</h1><p>Peep and Poppy’s guidelines for safer adventures online.</p></div></div><ul class="rules">${rules.map(([icon,title,detail])=>`<li><span aria-hidden="true">${icon}</span><div><strong>${title}</strong><p>${detail}</p></div></li>`).join('')}</ul><div class="page-action"><button class="primary" id="continue">Next: our badge adventure</button><p>Read together with a trusted grown-up.</p></div></section>`;document.getElementById('continue').onclick=()=>navigate('mission');}
function mission(){stage.innerHTML=`<section class="mission paper"><div class="mission-art"><img src="${art}" alt="Peep and Poppy ready to examine their tablet with Mama Clover nearby"><span class="art-caption">A little adventure. Eight smart choices.</span></div><div class="mission-copy"><p class="eyebrow">2 of 2 · Our mission</p><h1 tabindex="-1">Help us earn our<br>Cyber Smart Badge!</h1><p>Collect eight Safety Stars with Peep and Poppy.</p>${dialogue([['Peep','Hi! Peep and Poppy need your help!'],['Poppy','Sometimes things we see online are safe… but sometimes they are tricks called scams.'],['Peep','Can you spot the clues and decide what is SCAM and what is SAFE?'],['Poppy','Remember — if something online makes you worried, confused or unsure, always ask a trusted grown-up.']])}<button class="primary" id="start">START GAME</button><p class="small">No timer. Take your time and look carefully.</p></div></section>`;document.getElementById('start').onclick=()=>{current=0;stars=0;solved=false;navigate('level');};}
function messageCard(L){return `<div class="tablet"><div class="tablet-screen ${L.kind}"><div class="message-top">${L.kind==='polished'||L.kind==='website'?'<span class="game-logo" aria-hidden="true">✦</span>':''}<strong>${L.sender}</strong><span aria-hidden="true">•••</span></div>${L.expected?`<div class="web-address"><small>Website Peep wants to visit</small><span>${L.expected}</span><small>Website opened by the message</small><span>${L.actual}</span></div>`:''}<div class="message-text">${escapeHTML(L.message).replace(/\n/g,'<br>')}</div>${L.fakeButton?`<div class="pretend-button">${L.fakeButton}</div>`:''}${L.link?`<div class="pretend-link">${L.link}</div>`:''}${L.kind==='polished'?'<div class="polished-banner" aria-hidden="true">✦ &nbsp; HAPPY GAMES &nbsp; ✦</div>':''}</div><span class="tablet-home" aria-hidden="true"></span></div>`;}
function level(){const L=levels[current];stage.innerHTML=`<section class="case"><div class="case-heading"><div><p class="eyebrow">Level ${current+1} of 8</p><h1 tabindex="-1">${L.title}</h1></div><div class="collection"><span>Our Safety Stars</span>${starRow()}</div></div><div class="case-layout paper"><aside class="story-panel"><div class="scene-art"><img src="${art}" alt="Peep and Poppy investigating a message with their tablet"><span>${L.context}</span></div><div class="story-copy"><p class="scene-text">${L.scene}</p>${dialogue(L.dialogue)}</div></aside><div class="decision-panel"><p class="eyebrow">Look carefully at the clues</p>${messageCard(L)}${L.note?`<p class="scene-note">${L.note}</p>`:''}<fieldset class="choice-group"><legend>SCAM or SAFE?</legend><div class="choices"><button id="scam" class="choice scam"><span aria-hidden="true">✋</span> SCAM</button><button id="safe" class="choice safe"><span aria-hidden="true">✓</span> SAFE</button></div></fieldset><p class="try-again" id="retry" role="status" aria-live="polite"></p><p class="small decision-note">Choose below — the message is just part of our story.</p></div></div><section id="result" class="result" hidden aria-label="Safety lesson"></section></section>`;document.getElementById('scam').onclick=()=>choose('scam');document.getElementById('safe').onclick=()=>choose('safe');if(solved)showResult(false);}
function chime(){if(!sound)return;try{audioContext=audioContext||new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();[523.25,659.25,783.99].forEach((f,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain(),t=audioContext.currentTime+i*.12;o.connect(g);g.connect(audioContext.destination);o.frequency.value=f;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.07,t+.025);g.gain.exponentialRampToValueAtTime(.001,t+.3);o.start(t);o.stop(t+.32);});}catch(e){}}
function choose(answer){if(solved)return;if(answer!==levels[current].answer){document.getElementById('retry').textContent='Good try — look again. Who sent it? Is anything unusual, unexpected or asking for private information?';return;}solved=true;stars=Math.max(stars,current+1);chime();showResult(true);}
function showResult(scroll){const L=levels[current];for(const id of ['scam','safe']){const b=document.getElementById(id);b.disabled=true;b.classList.toggle('chosen',id===L.answer);}document.getElementById('retry').textContent='';const trail=stage.querySelector('.star-trail');trail.outerHTML=starRow();const result=document.getElementById('result');result.hidden=false;result.innerHTML=`<div class="reward"><span aria-hidden="true">★</span><div><p class="eyebrow">A smart choice!</p><h2 tabindex="-1">Safety Star ${current+1} collected!</h2></div></div><div class="result-columns"><div>${dialogue(L.reply)}</div><div class="safety-tip"><h3>Remember your safety tip</h3>${L.tips.map(t=>`<p>${t}</p>`).join('')}${L.checks?`<ul>${L.checks.map(t=>`<li>${t}</li>`).join('')}</ul>`:''}${L.after?`<p><strong>${L.after}</strong></p>`:''}</div></div><button class="primary" id="next">${current===7?'Collect our Cyber Smart Badge':'Next scene'}</button>`;document.getElementById('next').onclick=()=>{if(current===7)navigate('finish');else{current++;solved=false;render();}};if(scroll){result.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});result.querySelector('h2').focus({preventScroll:true});}}
function finish(){stage.innerHTML=`<section class="finish paper"><p class="eyebrow">All eight Safety Stars collected</p><h1 tabindex="-1">You’re a Cyber Smart Scam Spotter!</h1><div class="celebration"><div class="friends" aria-label="Peep and Poppy celebrate"><span class="friend peep"></span><span class="friend poppy"></span></div><div class="badge" aria-label="Cyber Smart Badge earned"><span aria-hidden="true">★</span><strong>CYBER<br>SMART</strong><small>Scam Spotter</small></div></div>${starRow()}${dialogue([['Peep','You did it!'],['Poppy','You’re becoming a brilliant Scam Spotter!']])}<h2>Remember your scam-spotting rules</h2><ul class="recap">${rules.map(([icon,title])=>`<li><span aria-hidden="true">${icon}</span> ${title}</li>`).join('')}</ul><div class="finish-actions"><button class="primary" id="again">Play again</button><a class="secondary" href="../">Choose another game</a></div></section>`;document.getElementById('again').onclick=()=>{current=0;stars=0;solved=false;navigate('mission');};}
document.getElementById('back').onclick=()=>navigate(screen==='mission'?'guidelines':'mission');
document.getElementById('sound').onclick=()=>{sound=!sound;document.getElementById('sound').textContent=sound?'Sound on':'Sound off';document.getElementById('sound').setAttribute('aria-pressed',String(sound));};
history.replaceState({scamScreen:'guidelines'},'');
window.addEventListener('popstate',event=>{screen=event.state?.scamScreen||'guidelines';render();});
render();
